function renderLearn(){view.innerHTML=`<div class="page-heading"><div><div class="eyebrow">TEMELDEN BAŞLA</div><h1>TAB Öğren</h1><p class="subtle">Kısa dersler, hemen deneyebileceğin örneklerle.</p></div></div><div class="lesson-list">${lessons.map(l=>`<article class="panel lesson-card"><div class="lesson-top"><span class="lesson-num">DERS 0${l.n}</span><span class="level-badge">${l.n<=5?'TEMEL':'TEKNİK'}</span></div><h3>${l.title}</h3><p>${l.description}</p><div class="lesson-tab">${l.tab}</div></article>`).join('')}</div>`}
