function openAudioStore(){return new Promise((resolve,reject)=>{const request=indexedDB.open('tabu-audio-library',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('recordings'))request.result.createObjectStore('recordings')};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
