function updateTimeBoard(timeOverride){const viewport=document.querySelector('#fretboard-viewport');if(!viewport||!activeTab)return;const audio=document.querySelector('#practice-audio'),usesPracticeClock=liveTracking||practiceStarted||practicePhase==='complete',current=Number.isFinite(timeOverride)?timeOverride:practiceClock.getMusicalTime({mediaTime:audio&&!usesPracticeClock?audio.currentTime:undefined}),scale=Math.max(42,viewport.clientWidth/4.4),playhead=viewport.clientWidth*.28,activeIndex=audio||usesPracticeClock?activePracticeEventAt(current):state.step;document.querySelectorAll('.time-note').forEach(node=>{const index=Number(node.dataset.index),time=practiceEventTime(activeTab.events[index],index),x=playhead+(time-current)*scale,status=liveStatuses[index];node.dataset.time=String(time);node.style.left=`${x}px`;node.classList.toggle('time-note-active',index===activeIndex);node.classList.toggle('time-note-past',time<=current&&index!==activeIndex);node.classList.toggle('correct',noteResultClass(status)==='correct');node.classList.toggle('wrong',noteResultClass(status)==='wrong');node.classList.toggle('missed',noteResultClass(status)==='missed');node.hidden=x< -55||x>viewport.clientWidth+55})}function syncPracticeToAudio(audio){if(!audio||!activeTab?.events?.length)return;updateTimeBoard();const index=activePracticeEventAt(practiceClock.getMusicalTime({mediaTime:audio.currentTime}));if(index<0||state.step===index)return;state.step=index;if(liveTracking){liveCandidateMidi=null;liveCandidateFrames=0;liveScored=false}setFretboardState(index);updateStepInfo()}function trackPracticeAudio(audio){cancelAnimationFrame(practiceAudioFrame);const tick=()=>{if(audio.paused||audio.ended){updateTimeBoard();return}syncPracticeToAudio(audio);practiceAudioFrame=requestAnimationFrame(tick)};tick()}
