function updateAudioDebug(frame=micFrame,result=micMatch){if(!debugAudio)return;const note=activeTab?.events?.[state.step]?.notes?.[0],expected=note&&expectedGuitarNote(note.string,note.fret),frequency=frame?.rawFrequency??frame?.detectedFrequency,detected=frequencyToNote(frequency),set=(id,value)=>{const el=document.querySelector(`#${id}`);if(el)el.textContent=value};set('debug-expected',expected?`String ${strings.indexOf(note.string)+1} · fret ${note.fret} · ${expected.label} · MIDI ${expected.midi} · ${expected.frequency.toFixed(2)} Hz`:'—');set('debug-detected',detected?`${detected.label} · MIDI ${detected.midi} · ${frequency.toFixed(2)} Hz`:'NO SIGNAL');set('debug-cents',expected&&frequency?`${centsDifference(frequency,expected.frequency).toFixed(1)} cents (±${PITCH_TOLERANCE_CENTS})`:'—');set('debug-signal',frame?`${(frame.level||0).toFixed(3)} RMS · ${(frame.confidence||0).toFixed(2)} confidence`:'—');set('debug-stable',frame?String(frame.stableFrames||0):'—');set('debug-match',result||'—');set('debug-state',result==='NO SIGNAL'?'NO SIGNAL':result==='MATCH ✓'?'CORRECT':result==='MATCH ✕'?'WRONG':frame?.signal&&frame?.stableFrames<5?'UNSTABLE':'LISTENING')}
